import logging
from taf.internal.managedobject import ManagedObject


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SshForwarding(ManagedObject):

    def __init__(self, ssh_connection, forward_address, **kwargs):
        super(SshForwarding, self).__init__(**kwargs)

        self._ssh_connection = ssh_connection
        self.add_prerequisite(self._ssh_connection)

        self._forward_address = forward_address

    def create_channel(self):
        channel = self._ssh_connection.get_forwarding_channel(
            self._forward_address.host, self._forward_address.port)
        return channel

    def _setup(self):
        logger.debug("setup ssh forwarding from address={} forwarding to {}:{}".format(
            self._ssh_connection.address, self._forward_address.host, self._forward_address.port))
